class Solution {
public:
    string addBinary(string a, string b) {
        int i = (int)a.size() - 1;
        int j = (int)b.size() - 1;
        int carry = 0;
        string res = "";
        while (i >= 0 || j >= 0 || carry) {
            int total = carry;
            if (i >= 0) total += a[i--] - '0';
            if (j >= 0) total += b[j--] - '0';
            res = (char)('0' + total % 2) + res;
            carry = total / 2;
        }
        return res;
    }
};

